//! 🧪️ Original paid semantic metadata survives exclusive payload loans and a separate granted acknowledgement.
use semio_framework_job::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
#[path="../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
#[global_allocator]
static ORIGINAL_DESCRIPTOR_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_outcome_descriptors_keep_same_payload_and_receipt_until_paid_ack(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let row=&law["grant"];let grant=RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize};
 let operation=OperationId(72013);let generation=Generation(19);
 for variant in 0..6{for pages in[0,1,32]{
  let bytes:Vec<u8>=(0..pages).map(|index|index as u8).collect();let mut prepared=original_payload::OriginalTestPayload::admit(operation,generation,JobPayloadStream::Preview,&bytes,1);let payload=prepared.builder.published().unwrap();let output=RetainedJobPayload::empty(JobPayloadStream::CommitOutput);let header=payload as*const RetainedJobPayload;let page=payload.page(0).map(|value|value.as_ptr());for index in 0..pages{assert_eq!(payload.page(index),Some(&[index as u8][..]));}
  let(mut descriptor,heap)=observe(||prepared.caller.turn(grant,|cx|{Ok(match variant{0=>JobOutcomeBorrow::admit_yield(cx),1=>JobOutcomeBorrow::admit_preview(cx,payload),2=>JobOutcomeBorrow::admit_checkpoint(cx,payload,17),3=>JobOutcomeBorrow::admit_complete(cx,Some(payload),Some(&output)),4=>JobOutcomeBorrow::admit_cancelled(cx),5=>JobOutcomeBorrow::admit_fault(cx,payload),_=>unreachable!()}.unwrap().unwrap().into_descriptor())}).unwrap());assert_eq!(heap,(0,0));assert_eq!(prepared.caller.receipt(),RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(descriptor.admission().progress(),prepared.caller.receipt());
  let(view,heap)=observe(||match variant{0=>descriptor.yielded(),1=>descriptor.preview(payload),2=>descriptor.checkpoint(payload),3=>descriptor.complete(Some(payload),Some(&output)),4=>descriptor.cancelled(),5=>descriptor.fault(payload),_=>unreachable!()}.unwrap());assert_eq!(heap,(0,0));assert!(std::ptr::eq(view.admission(),descriptor.admission()));let original=match view{JobOutcomeView::PreviewReady{payload,..}=>Some(payload),JobOutcomeView::CheckpointReady{state,applied_progress,..}=>{assert_eq!(applied_progress,17);Some(state)},JobOutcomeView::Complete{state,output,..}=>{assert!(output.unwrap().terminal_is_empty());state},JobOutcomeView::Fault{detail,..}=>Some(detail),_=>None};if let Some(original)=original{assert!(std::ptr::eq(original,header));assert_eq!(original.page(0).map(|value|value.as_ptr()),page);}
  if variant==1{let alternate=RetainedJobPayload::empty(JobPayloadStream::Preview);let(result,heap)=observe(||descriptor.preview(&alternate));assert!(result.is_err());assert_eq!(heap,(0,0));}
  for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,heap)=observe(||descriptor.acknowledge(denied));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert!(!descriptor.is_acknowledged());assert_eq!(payload as*const RetainedJobPayload,header);}
  let(step,heap)=observe(||descriptor.acknowledge(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:0,..Default::default()});assert_eq!(heap,(0,0));assert!(descriptor.is_acknowledged());
  let mut slot=JobOutcomeDescriptorSlot::empty();assert!(slot.retain(descriptor).is_ok());assert_eq!(slot.retirement_demands().copy_bytes,0);let slot_identity=slot.original().unwrap()as*const JobOutcomeDescriptor;let(step,heap)=observe(||slot.close_step(RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.original().unwrap()as*const JobOutcomeDescriptor,slot_identity);let(step,heap)=observe(||slot.close_step(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:0,..Default::default()});assert!(slot.is_empty());assert_eq!(heap,(0,0));let(_,heap)=observe(||drop(slot));assert_eq!(heap,(0,0));prepared.close();let released=prepared.caller.cumulative_receipt().released_bytes;assert_eq!(observe(||{drop(prepared);drop(output)}).1,(0,0));println!("[DEBUG] original descriptor variant={variant} pages={pages} samePayload sameAdmission metadataCopy0 independentACK deniedHeap0 physical={released} terminalDrop0");
 }}
}
